<script setup lang="ts">
import PreviewDatePicker from '../../features/preview/components/PreviewDatePicker.vue';
import PreviewSelect from '../../features/preview/components/PreviewSelect.vue';
import { computed, ref, watch } from 'vue';
import { usePreview, navigate, daysAgo, type Trace } from '../../features/preview/usePreviewStore';
import { dateOf } from '../../features/workbench/types';
import PageHeading from '../../features/preview/components/PageHeading.vue';
import TableFooter from '../../features/preview/components/TableFooter.vue';
import Icon from '../../features/workbench/components/WorkbenchIcon.vue';
const props=defineProps<{view:string}>(),s=usePreview();
const search=ref(''),date=ref(''),route=ref(''),result=ref(''),page=ref(1),range=ref('7'),from=ref(''),to=ref(''),detailOpen=ref(false),detail=ref<Trace|null>(null);
watch([search,date,route,result],()=>page.value=1);
const traces=computed(()=>s.traces.value.filter(t=>`${t.question} ${t.customer} ${t.conversationId}`.includes(search.value.trim())&&(!date.value||t.createdAt.slice(0,10)===date.value)&&(!route.value||t.route===route.value)&&(!result.value||t.result===result.value)));
const feedback=computed(()=>s.feedback.value.filter(t=>`${t.question} ${t.customer} ${t.reason}`.includes(search.value.trim())&&(!result.value||t.rating===result.value)));
const followups=computed(()=>s.wb.conversations.value.filter(c=>c.status==='WAITING_USER'||(c.status==='AI_ACTIVE'&&c.id===105)).filter(c=>`${c.customer} ${c.messages.find(m=>m.sender==='customer')?.content}`.includes(search.value.trim())));
function show(t:Trace){s.openTrace(t.id);}
function go(id:number){const active=s.wb.conversations.value.find(c=>c.id===id&&c.status!=='CLOSED');if(active){s.wb.select(id);navigate('support/workbench');}else navigate('support/history',id);}
const initial=Number(new URLSearchParams(window.location.hash.split('?')[1]).get('id'));if(initial){const t=s.traces.value.find(t=>t.id===initial);if(t)show(t);}
const period=computed(()=>{const end=range.value==='custom'&&to.value?new Date(to.value+'T23:59:59.999').getTime():Date.now();const start=range.value==='custom'&&from.value?new Date(from.value+'T00:00:00').getTime():new Date(new Date(end).setHours(0,0,0,0)).getTime()-(Number(range.value==='custom'?'7':range.value)-1)*86400000;return {start,end};});
const inPeriod=(value:string)=>{const t=Date.parse(value);return t>=period.value.start&&t<=period.value.end;};
const closed=computed(()=>s.histories.value.filter(h=>inPeriod(h.startedAt)));
const engaged=computed(()=>closed.value.length+s.wb.conversations.value.filter(c=>c.status!=='CLOSED'&&c.messages.some(m=>m.sender==='customer')&&inPeriod(c.messages[0]?.createdAt||c.lastMessageAt)).length);
const independent=computed(()=>closed.value.filter(h=>!h.human&&!h.requested&&h.messages.some(m=>m.sender==='ai')).length);
const handoff=computed(()=>closed.value.filter(h=>h.requested).length+s.wb.conversations.value.filter(c=>c.status!=='CLOSED'&&['WAITING_USER','HUMAN_ACTIVE'].includes(c.status)&&inPeriod(c.waitingSince||c.messages[0]?.createdAt||c.lastMessageAt)).length);
const human=computed(()=>closed.value.filter(h=>h.human).length+s.wb.conversations.value.filter(c=>c.status==='HUMAN_ACTIVE'&&inPeriod(c.messages[0]?.createdAt||c.lastMessageAt)).length);
const tickets=computed(()=>s.tickets.value.filter(t=>inPeriod(t.createdAt)));
const ratings=computed(()=>s.feedback.value.filter(t=>inPeriod(t.createdAt)));
const tokenTraces=computed(()=>s.traces.value.filter(t=>inPeriod(t.createdAt)));
const knownTokens=computed(()=>tokenTraces.value.reduce((n,t)=>n+(t.input||0)+(t.output||0),0));
const percent=(n:number,d:number)=>d?`${Math.round(n/d*100)}%`:'—';
const trend=computed(()=>Array.from({length:Math.min(30,Math.max(1,Math.floor((period.value.end-period.value.start)/86400000)+1))},(_,i)=>{const start=period.value.start+i*86400000,end=start+86400000;const list=closed.value.filter(h=>Date.parse(h.startedAt)>=start&&Date.parse(h.startedAt)<end);return {day:new Date(start).toLocaleDateString('zh-CN',{month:'2-digit',day:'2-digit'}),ai:list.filter(h=>!h.human&&!h.requested).length,human:list.filter(h=>h.human).length};}));
const max=computed(()=>Math.max(3,Math.ceil(Math.max(0,...trend.value.map(d=>Math.max(d.ai,d.human)))/3)*3));
function line(kind:'ai'|'human'){return trend.value.map((d,i)=>`${48+(i/Math.max(1,trend.value.length-1))*650},${190-d[kind]/max.value*145}`).join(' ');}
const typeCounts=computed(()=>['退货退款','换货','修改收货地址','仅退款','其他售后'].map((name,i)=>({name,count:tickets.value.filter(t=>t.types.includes(['RETURN_REFUND','EXCHANGE','CHANGE_ADDRESS','REFUND_ONLY','OTHER'][i] as never)).length})));
const titles:Record<string,string>={dashboard:'数据分析',traces:'回复路由记录',feedback:'回答反馈',followups:'待跟进问题'};
const descriptions:Record<string,string>={dashboard:'从接待、转人工和知识反馈，了解 AI 的实际使用情况。',traces:'查看每次 AI 提问的判断、知识依据与 Token 使用情况。',feedback:'保留对单条 AI 回复的赞、踩和原因。',followups:'展示当前仍需补充信息或人工接入的问题，接入或完结后自动移出。'};
</script>
<template><div class="pv-page"><PageHeading :title="titles[view]" :description="descriptions[view]" eyebrow="分析与反馈"/>
<template v-if="view==='dashboard'"><div class="pv-card pv-page-toolbar pv-dashboard-toolbar"><span class="pv-panel-meta">统计范围</span><div v-if="view==='dashboard'" class="pv-range"><button v-for="r in [{id:'1',name:'今天'},{id:'7',name:'近 7 天'},{id:'30',name:'近 30 天'},{id:'custom',name:'自定义'}]" :key="r.id" :class="{active:range===r.id}" @click="range=r.id">{{r.name}}</button></div></div><div v-if="range==='custom'" class="pv-filters pv-custom-date"><label>开始日期 <PreviewDatePicker v-model="from" type="date" :max="to||undefined"/></label><span>至</span><label>结束日期 <PreviewDatePicker v-model="to" type="date" :min="from||undefined"/></label></div><div class="pv-metric-grid"><article class="pv-card"><div><span>有效接待会话</span><Icon name="ChatDotRound"/></div><strong>{{engaged}}</strong><small>客户实际发起提问的会话</small></article><article class="pv-card"><div><span>AI 独立完结率</span><Icon name="MagicStick"/></div><strong>{{percent(independent,closed.length)}}</strong><small>{{independent}} / {{closed.length}} 次已完结会话</small></article><article class="pv-card"><div><span>请求 / 实际人工接入</span><Icon name="User"/></div><strong>{{handoff}}<em>/ {{human}}</em></strong><small>请求人工与实际接入分别统计</small></article><article class="pv-card"><div><span>业务操作成功</span><Icon name="CircleCheck"/></div><strong>{{s.businessEvents.value.filter(e=>inPeriod(e.createdAt)).length}}</strong><small>不包含查询或工单完成标记</small></article></div>
<div class="pv-dashboard-grid"><section class="pv-card pv-chart"><div class="pv-panel-heading"><div><strong>会话完结趋势</strong><small>按会话创建日期归组，查看当前完结结果</small></div><div class="pv-chart-legend"><span><i class="blue"></i>AI 独立完结</span><span><i class="green"></i>人工接待完结</span></div></div><svg viewBox="0 0 750 235" role="img" aria-label="AI 与人工会话完结趋势图"><g v-for="i in 4" :key="i"><line x1="48" x2="700" :y1="45+(i-1)*48.3" :y2="45+(i-1)*48.3" stroke="var(--wb-line-soft)"/><text x="16" :y="49+(i-1)*48.3" fill="var(--wb-text-muted)" font-size="11">{{Math.round(max*(4-i)/3)}}</text></g><polyline :points="line('ai')" fill="none" stroke="var(--wb-blue)" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><polyline :points="line('human')" fill="none" stroke="var(--wb-success)" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><g v-for="(d,i) in trend" :key="d.day"><text v-if="trend.length<=8||i%5===0||i===trend.length-1" :x="48+(i/Math.max(1,trend.length-1))*650" y="222" fill="var(--wb-text-muted)" text-anchor="middle" font-size="11">{{d.day}}</text><circle :cx="48+(i/Math.max(1,trend.length-1))*650" :cy="190-d.ai/max*145" r="3" fill="var(--wb-blue)"><title>{{d.day}} AI {{d.ai}} / 人工 {{d.human}}</title></circle></g></svg></section><section class="pv-card pv-dashboard-summary"><h3>回答反馈</h3><div class="pv-rating-number">{{percent(ratings.filter(r=>r.rating==='踩').length,ratings.length)}}<span>已评价回复中的踩占比</span></div><div class="pv-summary-line"><span>赞</span><strong>{{ratings.filter(r=>r.rating==='赞').length}}</strong></div><div class="pv-summary-line"><span>踩</span><strong>{{ratings.filter(r=>r.rating==='踩').length}}</strong></div><button class="wb-text-button" @click="navigate('analysis/feedback')">查看回答反馈 →</button></section></div>
<div class="pv-dashboard-grid"><section class="pv-card pv-dashboard-summary"><div class="pv-panel-heading"><strong>客服工单</strong><button class="wb-text-button" @click="navigate('support/todos')">查看全部 →</button></div><div class="pv-ticket-summary"><div><strong>{{tickets.length}}</strong><span>期间创建</span></div><div><strong>{{tickets.filter(t=>t.completion==='DONE').length}}</strong><span>当前已完成</span></div><div><strong>{{tickets.filter(t=>t.completion==='PENDING').length}}</strong><span>当前待完成</span></div></div><div v-for="t in typeCounts" :key="t.name" class="pv-type-bar"><span>{{t.name}}</span><div><i :style="{width:`${tickets.length?t.count/tickets.length*100:0}%`}"></i></div><strong>{{t.count}}</strong></div><small class="pv-muted">同一工单可含多种诉求，各类型不相加为总量。</small></section><section class="pv-card pv-dashboard-summary"><h3>Token 使用</h3><div class="pv-rating-number">{{knownTokens.toLocaleString()}}<span>有用量记录的输入 + 输出 Token</span></div><p class="pv-muted">{{tokenTraces.length}} 条回复路由记录中，{{tokenTraces.filter(t=>t.input!==null&&t.output!==null).length}} 条有用量数据。缺失值保留为「—」。</p><button class="wb-text-button" @click="navigate('analysis/traces')">查看回复路由 →</button><p class="pv-settings-note">不包含知识入库、召回测试与配置校验；AI 辅助建议的生成也计入模型用量。</p></section></div>
<details class="pv-card pv-metric-notes"><summary>查看统计口径</summary><p>有效接待排除仅打开窗口或只收到打招呼的会话。AI 独立完结必须有 AI 回复，且没有请求或实际人工介入；分母为期间创建且当前已完结的有效会话，分母为 0 时显示「—」。</p><p>工单按创建日期与当前完成标记统计；业务操作按成功发生日期统计。申请退款不等于退款到账，标记工单完成不计为业务执行成功。</p></details></template>
<div v-else class="pv-card"><div class="pv-filters"><div class="pv-search"><Icon name="Search"/><input v-model="search" placeholder="搜索客户、问题或会话" aria-label="搜索分析记录"/></div><template v-if="view==='traces'"><PreviewDatePicker v-model="date" type="date" aria-label="提问日期"/><PreviewSelect v-model="route" aria-label="路由筛选"><option value="">全部路由</option><option>知识问答</option><option>订单查询</option><option>售后咨询</option></PreviewSelect><PreviewSelect v-model="result" aria-label="结果筛选"><option value="">全部结果</option><option>已回复</option><option>请求人工</option></PreviewSelect></template><PreviewSelect v-else-if="view==='feedback'" v-model="result" aria-label="评价筛选"><option value="">全部评价</option><option>赞</option><option>踩</option></PreviewSelect></div><div class="pv-table-scroll">
<table v-if="view==='traces'" class="pv-table"><thead><tr><th>客户提问</th><th>路由 / 结果</th><th>输入 / 输出 Token</th><th>总 Token</th><th>提问时间</th><th>操作</th></tr></thead><tbody><tr v-for="t in traces.slice((page-1)*8,page*8)" :key="t.id"><td class="pv-wide-cell"><strong>{{t.question}}</strong><small>{{t.customer}} · 会话 #{{t.conversationId}}</small></td><td><span class="pv-tag blue">{{t.route}}</span><small>{{t.result}}</small></td><td>{{t.input??'—'}} <span class="pv-muted">/ {{t.output??'—'}}</span></td><td>{{t.input!==null&&t.output!==null?t.input+t.output:'—'}}</td><td>{{dateOf(t.createdAt)}}</td><td><button class="wb-text-button" @click="show(t)">查看详情</button></td></tr></tbody></table>
<table v-else-if="view==='feedback'" class="pv-table"><thead><tr><th>客户提问</th><th>评价</th><th>反馈原因</th><th>反馈时间</th><th>操作</th></tr></thead><tbody><tr v-for="t in feedback.slice((page-1)*8,page*8)" :key="t.id"><td class="pv-wide-cell"><strong>{{t.question}}</strong><small>{{t.customer}} · 会话 #{{t.conversationId}}</small></td><td><span class="pv-tag" :class="t.rating==='赞'?'green':'amber'">{{t.rating}}</span></td><td>{{t.reason}}</td><td>{{dateOf(t.createdAt)}}</td><td><button class="wb-text-button" @click="show(t)">查看对应回复</button></td></tr></tbody></table>
<table v-else class="pv-table"><thead><tr><th>客户</th><th>当前问题</th><th>跟进原因</th><th>最近消息</th><th>操作</th></tr></thead><tbody><tr v-for="c in followups.slice((page-1)*8,page*8)" :key="c.id"><td><div class="pv-customer"><span class="wb-avatar" :class="c.tone">{{c.avatar}}</span><strong>{{c.customer}}</strong></div></td><td class="pv-wide-cell">{{c.messages.filter(m=>m.sender==='customer'&&m.kind==='text').at(-1)?.content||'客户已发送订单卡片，请核实具体诉求'}}</td><td><span class="pv-tag" :class="c.status==='WAITING_USER'?'amber':'blue'">{{c.status==='WAITING_USER'?'等待人工接入':'等待补充信息'}}</span></td><td>{{dateOf(c.lastMessageAt)}}</td><td><button class="wb-text-button" @click="go(c.id)">前往会话</button></td></tr></tbody></table>
<div v-if="!(view==='traces'?traces.length:view==='feedback'?feedback.length:followups.length)" class="pv-empty"><Icon name="CircleCheck"/><strong>没有符合条件的记录</strong><span>{{view==='followups'?'已接入或完结的会话会自动移出':'调整筛选条件后再试'}}</span></div></div><TableFooter v-model:page="page" :total="view==='traces'?traces.length:view==='feedback'?feedback.length:followups.length"/></div>
</div></template>
